# 阶段1: 检测环
def has_cycle(head):
  slow = fast = head
  while fast and fast.next:
    slow = slow.next
    fast = fast.next.next
    if slow == fast:
      return True
  return False

# 阶段2: 找环起点
def cycle_start(head):
  slow = fast = head
  while fast and fast.next:
    slow = slow.next; fast = fast.next.next
    if slow == fast:
      break
  if not fast or not fast.next:
    return None
  slow = head
  while slow != fast:
    slow = slow.next; fast = fast.next
  return slow
